import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();

        int[][] students = new int[n][5];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < 5; j++) {
                students[i][j] = sc.nextInt();
            }
        }

        int bestCount = -1;
        int bestStudent = 1;

        for (int i = 0; i < n; i++) {
            Set<Integer> sameClass = new HashSet<>();
            for (int j = 0; j < n; j++) {
                if (i == j) continue;
                for (int grade = 0; grade < 5; grade++) {
                    if (students[i][grade] == students[j][grade]) {
                        sameClass.add(j);
                        break;
                    }
                }
            }

            if (sameClass.size() > bestCount) {
                bestCount = sameClass.size();
                bestStudent = i + 1;
            }
        }

        System.out.println(bestStudent);
    }
}

#include <iostream>
#include <set>
using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    cin >> n;

    int students[1001][5];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < 5; j++) {
            cin >> students[i][j];
        }
    }

    int bestCount = -1;
    int bestStudent = 1;

    for (int i = 0; i < n; i++) {
        set<int> sameClass;
        for (int j = 0; j < n; j++) {
            if (i == j) continue;
            for (int grade = 0; grade < 5; grade++) {
                if (students[i][grade] == students[j][grade]) {
                    sameClass.insert(j);
                    break;
                }
            }
        }

        if ((int)sameClass.size() > bestCount) {
            bestCount = sameClass.size();
            bestStudent = i + 1;
        }
    }

    cout << bestStudent << endl;

    return 0;
}
